package com.day18.auth.security; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; @Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filter(HttpSecurity h)throws Exception{return h.csrf(AbstractHttpConfigurer::disable).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/**").permitAll().anyRequest().authenticated()).build();} }
